const maps=[['wonderland',null,'Wonderland','A narrative topography following Alice’s dream from the rabbit hole through woods, houses, gardens, shore, and court.'],['hall','wonderland','The Rabbit-Hole and Long Hall','A vertical fall opens into the many-doored hall, the tiny garden door, and the Pool of Tears.'],['rabbitHouse','wonderland','The White Rabbit’s House','A small house that becomes enormous relative to Alice after another abrupt change of size.'],['duchessHouse','wonderland','The Duchess’s House','A woodland cottage whose smoke-filled kitchen is ruled by pepper, flying crockery, and unstable identities.'],['queenGrounds','wonderland','The Queen of Hearts’ Grounds','Rose beds, procession routes, a disorderly croquet field, and the road toward the Mock Turtle’s shore.'],['court','queenGrounds','The Court of Hearts','A ceremonial chamber where tarts, testimony, nonsense rules, and Alice’s growing confidence collide.']].map(([s,p,name,description])=>({...base,id:M(s),parentMapId:p?M(p):null,name,description,imageId:I(`map-${s}`),imageWidth:mapInfo[s][0],imageHeight:mapInfo[s][1],scalePixelsPerUnit:null,scaleUnit:null,levelGroupId:null,levelIndex:0,levelLabel:''}))
