const charRows=[
 ['alice','Alice',[],'An inquisitive, practical-minded girl whose changing size and growing confidence test every rule Wonderland presents.','#6c83a1'],['white-rabbit','White Rabbit',[],'An anxious court official whose waistcoat, watch, and fear of lateness draw Alice underground.','#b8b0a1'],['mouse','The Mouse',[],'A dignified swimmer whose sensitivity about cats and dogs repeatedly collides with Alice’s conversation.','#8f7967'],['dodo','The Dodo',[],'A solemn participant in the Pool of Tears party who turns drying off into a leaderless race and prize ceremony.','#7d6680'],['bill','Bill the Lizard',[],'The White Rabbit’s gardener and reluctant chimney climber, later serving as a slate-scratching juror.','#7b9366'],['puppy','The Puppy',[],'A playful ordinary animal made dangerous only by Alice’s temporary smallness.','#a77b56'],['caterpillar','The Caterpillar',[],'A hookah-smoking questioner who challenges Alice’s account of identity and explains the mushroom’s two effects.','#708d74'],['pigeon','The Pigeon',[],'A nest-guarding bird who interprets Alice’s elongated neck as proof that she is a serpent.','#817a72'],['fish-footman','Fish Footman',[],'A liveried messenger who delivers the Queen’s invitation to the Duchess with elaborate formality.','#738895'],['frog-footman','Frog Footman',[],'The Duchess’s placid doorkeeper, convinced that knocking is pointless amid the kitchen’s noise.','#6d8b70'],['duchess','The Duchess',[],'A volatile noblewoman whose kitchen fury becomes intrusive friendliness and relentless moralising at croquet.','#8a6473'],['cook','The Cook',[],'The Duchess’s pepper-loving cook, willing to throw crockery and later answer a court with defiance.','#876f58'],['baby','The Duchess’s Baby',[],'A violently sneezing infant whose features settle into those of a pig once Alice removes it from the kitchen.','#aa806e'],['cheshire-cat','Cheshire Cat',[],'A calm, grinning guide who treats universal madness as obvious and controls how much of itself remains visible.','#9b6785'],['hatter','The Hatter',['Mad Hatter'],'A trapped tea-drinker and nervous court witness whose quarrel with Time has stopped the table at six o’clock.','#8d6f50'],['march-hare','March Hare',[],'The Hatter’s host, quick to contradict Alice and rearrange places without improving the tea.','#93785a'],['dormouse','Dormouse',[],'A sleepy guest repeatedly awakened to tell a treacle-well story and later summoned as a witness.','#8d806c'],['queen','Queen of Hearts',[],'A furious ruler who answers inconvenience with death sentences and turns play, law, and hospitality into intimidation.','#a33f4c'],['king','King of Hearts',[],'A timid monarch and improvised judge who invents rules while trying to appear authoritative.','#967646'],['gryphon','The Gryphon',[],'A blunt royal guide who knows the Queen’s executions are mostly performance and escorts Alice to the shore and trial.','#6f748d'],['mock-turtle','The Mock Turtle',[],'A melancholy creature devoted to memories of submarine schooling, dances, and beautiful soup.','#668b88'],['knave','Knave of Hearts',[],'The silent defendant accused of stealing the Queen’s tarts.','#9b4e55'],['card-gardeners','Two, Five, and Seven',[],'Three card gardeners painting white roses red to conceal a planting error from the Queen.','#a8565b'],['jurors','The Jury',[],'Twelve birds and beasts who write everything down before they understand either the charge or the evidence.','#796f68']]
