const itemRows=[['watch','White Rabbit’s Pocket Watch','A waistcoat watch that first makes the Rabbit extraordinary and later becomes an object of tea-table repair.','tool'],['golden-key','Tiny Golden Key','A small key that opens the door to the Queen’s garden but repeatedly becomes unreachable at the wrong size.','key'],['drink-me','“DRINK ME” Bottle','A labelled bottle whose mixed flavours shrink Alice to ten inches.','consumable'],['eat-me','“EAT ME” Cake','A currant-lettered cake that makes Alice expand until her head reaches the hall ceiling.','consumable'],['fan-gloves','Fan and White Kid Gloves','The Rabbit’s dropped accessories; the fan unexpectedly shrinks Alice while she searches for an escape.','clothing'],['mushroom','Mushroom Pieces','Opposite sides of the Caterpillar’s mushroom let Alice deliberately grow or shrink.','consumable'],['hookah','Caterpillar’s Hookah','The Caterpillar’s smoking pipe, carried with unhurried composure atop the mushroom.','tool'],['pepper','Pepper Pot','The kitchen’s overwhelming seasoning provokes sneezing and mirrors the Duchess’s temper.','container'],['tea-set','Mad Tea Service','Cups, plates, bread-and-butter, and a teapot circulate around a table where time never advances.','container'],['flamingo','Flamingo Croquet Mallet','A live bird forced into the shape of sporting equipment, rarely facing the ball at the correct moment.','tool'],['tarts','Queen’s Tarts','A tray of pastries at the centre of the Knave’s criminal trial.','food'],['letter','Unsigned Letter','A verse offered as decisive evidence despite containing neither signature nor clear connection to the theft.','document']]
