mkdir('public/library/alice-in-wonderland/art/items')
for(const [s,name] of itemRows){write(`public/library/alice-in-wonderland/art/items/${s}.svg`,itemSvg(name,itemArt[s]));blobs.push(image(`item-${s}`,`${repo}/art/items/${s}.svg`,'image/svg+xml'))}
const items=itemRows.map(([s,name,description,type])=>({...base,id:Item(s),name,description,type,imageId:I(`item-${s}`),tags:[]}))

const chapterTitles=['Down the Rabbit-Hole','The Pool of Tears','A Caucus-Race and a Long Tale','The Rabbit Sends in a Little Bill','Advice from a Caterpillar','Pig and Pepper','A Mad Tea-Party','The Queen’s Croquet-Ground','The Mock Turtle’s Story','The Lobster Quadrille','Who Stole the Tarts?','Alice’s Evidence']
const timelineId=id('timeline','dream')
const chapters=chapterTitles.map((title,i)=>({...base,id:Ch(i+1),timelineId,number:i+1,title,summary:['Curiosity carries Alice from the riverbank through a slow fall and a hall where size prevents entry to a beautiful garden.','A fan, a flood of tears, and an offended Mouse turn Alice’s private confusion into a crowded swim.','The wet creatures attempt history, racing, prizes, and a tale before Alice’s talk of Dinah empties the shore.','Mistaken for a servant, Alice grows inside the Rabbit’s house, escapes as a tiny figure, and faces an enormous puppy.','The Caterpillar questions Alice’s identity, gives her control of size, and a Pigeon mistakes her long neck for a serpent.','Ceremonial footmen lead to a violent kitchen, a pig-baby, and the Cheshire Cat’s directions toward two kinds of madness.','At a perpetual tea party, riddles replace answers, Time refuses to move, and Alice finally reaches the garden.','Card gardeners, a royal procession, chaotic croquet, and a bodiless Cat expose the machinery of the Queen’s authority.','The Duchess finds morals everywhere before the Gryphon takes Alice to hear the Mock Turtle’s account of school.','The Lobster Quadrille and songs give way to Alice’s altered recitations and the sudden summons to a trial.','The court announces the stolen tarts, records evidence before understanding it, and examines increasingly absurd witnesses.','Alice grows past fear, disputes the court’s rules and evidence, and wakes as the pack descends.'][i],status:'final',tags:[],povCharacterIds:[C('alice')]}))

const beats=[
 [1,'bank-rabbit','A Rabbit with a Watch','Alice leaves the sleepy riverbank after seeing a waistcoated White Rabbit consult a watch.','riverbank',{alice:'Curiosity overcomes drowsiness and sends her after the first impossible thing she sees.','white-rabbit':'Hurries across the field, focused entirely on being late.'},2,['watch']],
 [1,'fall','Down the Well','The tunnel drops into a deep shaft lined with cupboards and shelves.','shaft',{alice:'Falls slowly enough to inspect the walls, replace an empty jar safely, and speculate about the earth.'},3,[]],
 [1,'key-door','The Key and the Garden','In the locked hall Alice discovers a golden key and a tiny door onto a beautiful garden.','long-hall',{alice:'Maps the hall’s doors carefully and identifies the garden as the destination she cannot yet reach.'},2,['golden-key']],
 [1,'drink','Shutting Up Like a Telescope','Alice drinks from the labelled bottle and shrinks, only to find the key still on the table.','glass-table',{alice:'Becomes ten inches tall, pleased with the result until the unreachable key reveals the new problem.'},3,['drink-me','golden-key']],
 [1,'cake-growth','Curiouser and Curiouser','The cake makes Alice grow until her head presses against the ceiling.','long-hall',{alice:'Expands beyond the hall’s scale and begins to cry from frustration and isolation.'},4,['eat-me']],
 [2,'rabbit-fan','The Rabbit Drops His Errand','The returning Rabbit mistakes giant Alice for a threat and abandons his fan and gloves.','long-hall',{alice:'Tries to ask for help but frightens the Rabbit away with her enormous presence.','white-rabbit':'Drops the Duchess’s fan and gloves and flees from the giant voice.'},3,['fan-gloves']],
 [2,'fan-shrink','The Fan’s Second Effect','While questioning who she has become, Alice fans herself and shrinks into her own tears.','tear-pool',{alice:'Tests childhood identities until the fan reduces her suddenly and casts her into the pool.'},4,['fan-gloves']],
 [2,'mouse-swim','Company in the Pool','Alice meets a Mouse and attempts conversation while both swim toward shore.','tear-pool',{alice:'Searches for a safe topic but repeatedly mentions cats and dogs to an increasingly offended listener.',mouse:'Agrees to lead the way out while recoiling from Alice’s tactless references to predators.'},2,[]],
 [2,'pool-party','A Crowded Swim','Birds and animals gather around Alice and the Mouse in the expanding pool.','tear-pool',{alice:'Swims among an unlikely crowd and follows its collective movement toward land.',mouse:'Keeps authority through the confusion and promises a history that will dry the party.',dodo:'Reaches the shore wet and uncomfortable, ready to entertain another solution.'},2,[]],
 [3,'dry-history','The Driest Thing','The Mouse recites English history as a literal drying method.','pool-shore',{alice:'Listens anxiously, more concerned with cold clothes than conquest.',mouse:'Delivers historical prose with solemn confidence and grows irritated by interruptions.',dodo:'Waits among the wet company for a more effective procedure.'},2,[]],
 [3,'caucus','A Race without Rules','The Dodo starts a circular race with no marked beginning or end.','pool-shore',{alice:'Runs with the others until everyone independently decides the race has lasted long enough.',dodo:'Declares that all have won, converting disorder into a ceremonial result.',mouse:'Participates without allowing the race to settle its grievance with Alice.'},2,[]],
 [3,'prizes','Prizes for Everyone','Alice distributes sweets and receives her own thimble back as a prize.','pool-shore',{alice:'Accepts the Dodo’s solemn presentation despite recognising that the gift came from her pocket.',dodo:'Presides over the prize-giving with complete seriousness.',mouse:'Waits for attention to return to the promised personal tale.'},2,[]],
 [3,'mouse-tale','A Tale Shaped Like a Tail','The Mouse recounts Fury’s legal threat, but Alice’s wandering attention ends the conversation.','pool-shore',{alice:'Confuses the Mouse’s spoken tale with the shape of its tail and loses the chance to repair the offence.',mouse:'Leaves in anger after concluding that Alice is not listening.'},3,[]],
 [3,'dinah-scatter','Dinah Empties the Shore','Alice praises Dinah’s hunting ability and the remaining creatures flee.','pool-shore',{alice:'Finds herself alone after again treating affection for Dinah as harmless conversation.',dodo:'Withdraws with the other birds when Alice describes a cat skilled at catching birds.'},2,[]],
 [4,'rabbit-mary-ann','Mistaken for Mary Ann','The Rabbit orders Alice to fetch gloves and a fan from his house.','rabbit-front',{alice:'Accepts the mistaken identity because the errand offers shelter and direction.','white-rabbit':'Treats Alice as his absent maid and demands the accessories before the Duchess notices.'},2,['fan-gloves']],
 [4,'house-growth','An Arm out of the Window','A bottle in the Rabbit’s bedroom makes Alice fill the house.','upstairs-room',{alice:'Braces an arm through the window and a foot up the chimney while trying to understand another extreme size.'},4,[]],
 [4,'bill-chimney','Bill Goes Down the Chimney','The crowd sends Bill to remove Alice, who kicks him out through the flue.','chimney',{alice:'Listens to the rescue debate and defends the only vulnerable opening with one sharp kick.','white-rabbit':'Directs ladders, ropes, and servants from the yard while refusing to enter himself.',bill:'Descends reluctantly and is launched back into the yard before reaching the room.'},4,[]],
 [4,'pebble-cakes','Pebbles Become Cakes','Thrown pebbles turn into cakes; Alice eats one and shrinks enough to escape.','rabbit-yard',{alice:'Recognises the transformation as a possible remedy, becomes small, and runs into the wood.','white-rabbit':'Keeps the yard mobilised as the giant occupant suddenly disappears from the house.',bill:'Recovers among the helpers after the chimney flight.'},3,['eat-me']],
 [4,'puppy-play','The Enormous Puppy','Tiny Alice distracts a puppy with a stick while avoiding its playful paws.','puppy-wood',{alice:'Uses the puppy’s desire to play as cover, then retreats exhausted before affection becomes crushing.',puppy:'Bounds after the stick and Alice with harmless enthusiasm magnified by her small scale.'},3,[]],
 [5,'caterpillar-question','Who Are You?','The Caterpillar demands an account of identity that Alice can no longer give confidently.','mushroom',{alice:'Explains that repeated bodily change has made the morning self difficult to claim.',caterpillar:'Questions every vague answer from a position of unhurried control.'},2,['hookah']],
 [5,'father-william','A Recitation Gone Wrong','Alice’s remembered verses emerge as an altered argument between Father William and his son.','mushroom',{alice:'Attempts proof of identity through memory and hears the familiar poem return transformed.',caterpillar:'Judges the recitation wrong from beginning to end without offering reassurance.'},2,[]],
 [5,'mushroom-sides','One Side and the Other','The Caterpillar explains how opposite sides of the mushroom change size.','mushroom',{alice:'Collects both pieces and begins experimentally balancing growth against shrinkage.',caterpillar:'Leaves after giving the first reliable rule Alice has received in Wonderland.'},3,['mushroom','hookah']],
 [5,'pigeon-serpent','Serpent!','Alice’s elongated neck enters a nest and the Pigeon accuses her of seeking eggs.','pigeon-tree',{alice:'Defends being a girl while conceding that she has eaten eggs, which weakens her argument.',pigeon:'Guards the nest fiercely and treats shape and appetite as sufficient evidence.'},3,['mushroom']],
 [5,'alice-right-size','Nine Inches to a Foot','Alice uses both mushroom pieces until she reaches a manageable height.','mushroom',{alice:'Gains deliberate control over size and sets off toward the nearby house with both pieces saved.'},2,['mushroom']],
 [6,'footmen','An Invitation at the Door','Fish and Frog footmen exchange a huge invitation while the kitchen crashes behind them.','footmen-walk',{alice:'Studies the ceremony and asks how to enter a house whose door is already within reach.','fish-footman':'Delivers the Queen’s croquet invitation with theatrical precision.','frog-footman':'Receives the message and explains that knocking cannot be heard over the kitchen noise.'},2,[]],
 [6,'pepper-kitchen','Pig and Pepper','Alice enters a kitchen filled with smoke, pepper, sneezing, and thrown cookware.','duchess-kitchen',{alice:'Tries to protect the baby while questioning a household that treats danger as normal.',duchess:'Nurses the baby roughly, sings a violent lullaby, and prepares to leave for croquet.',cook:'Stirs the soup, uses excessive pepper, and throws dishes without regard for anyone nearby.',baby:'Sneezes and howls amid the pepper and commotion.','cheshire-cat':'Grins from the hearth, untouched by the household’s disorder.'},4,['pepper']],
 [6,'crockery-cauldron','Crockery and Cauldron','The cook hurls pans and plates while the Duchess flings the baby to Alice and leaves for croquet.','kitchen-hearth',{alice:'Catches the baby before the next piece of crockery crosses the smoky room.',duchess:'Hands off responsibility as abruptly as she handled it and departs for the Queen’s game.',cook:'Rules the hearth through soup, pepper, and missiles, ignoring the danger to everyone nearby.',baby:'Howls in Alice’s arms while pans break around the cauldron.','cheshire-cat':'Watches the transfer from above the hearth with the same unexplained grin.'},4,['pepper']],
 [6,'baby-rescue','The Baby Becomes a Pig','Outside, Alice’s rescued infant develops snout and trotters and runs into the wood.','pig-path',{alice:'Sets the transformed child down, relieved that a pig may fare better than a baby in that house.',baby:'Completes the change into a pig and trots away independently.'},3,[]],
 [6,'cat-directions','We’re All Mad Here','The Cheshire Cat directs Alice toward the Hatter or March Hare and disappears by degrees.','cheshire-tree',{alice:'Chooses the March Hare’s direction while insisting that she does not want to be among mad people.','cheshire-cat':'Explains that madness is unavoidable and controls the conversation by vanishing and returning.'},2,[]],
 [7,'no-room','No Room at the Table','The tea party rejects Alice despite many empty places.','tea-table',{alice:'Takes a large chair without invitation and answers rudeness with increasingly direct objections.',hatter:'Inspects Alice, offers a personal remark, and proposes a riddle without an answer.','march-hare':'Insists there is no room and offers nonexistent wine.',dormouse:'Sleeps between the hosts, available as cushion and occasional participant.'},3,['tea-set','watch']],
 [7,'time-stopped','It Is Always Six O’Clock','The Hatter explains his quarrel with Time and the endless movement around the table.','tea-table',{alice:'Attempts to apply ordinary logic to a clock that reports days rather than hours.',hatter:'Recounts the failed concert and treats Time as a person who now refuses every request.','march-hare':'Confirms the broken routine while dipping the watch into tea.',dormouse:'Wakes only when pinched or required for the next part of the conversation.'},2,['tea-set','watch']],
 [7,'treacle-well','The Three Sisters in the Well','The Dormouse tells of sisters drawing things beginning with M from a treacle well.','tea-table',{alice:'Interrupts each impossible detail until the hosts accuse her of speaking too much.',hatter:'Polices the story only when Alice’s questions threaten its momentum.','march-hare':'Supports each contradiction and shifts seats when the table becomes inconvenient.',dormouse:'Builds the treacle-well tale while repeatedly slipping back toward sleep.'},2,['tea-set']],
 [7,'leave-tea','The Stupidest Tea-Party','Alice leaves as the hosts try to put the Dormouse into the teapot.','tea-table',{alice:'Rejects the company’s rules and notices a door set into a tree.',hatter:'Ignores Alice’s departure and helps force the Dormouse into the teapot.','march-hare':'Joins the Hatter’s final indignity without asking Alice to return.',dormouse:'Is handled as part of the tea service while barely awake.'},3,['tea-set']],
 [7,'garden-entry','At Last in the Garden','The tree door returns Alice to the hall; mushroom, key, and tiny door finally work in sequence.','tiny-door',{alice:'Uses what she has learned about size to unlock and pass through the garden door.','cheshire-cat':'Remains absent, but its directions have delivered Alice to the next choice.'},3,['mushroom','golden-key']],
 [8,'painting-roses','Painting the Roses Red','Alice finds three gardeners hiding their mistake with red paint.','rose-bush',{alice:'Questions the gardeners and quickly understands that fear, not horticulture, drives the work.','card-gardeners':'Paint frantically and blame one another while listening for the Queen’s approach.'},2,[]],
 [8,'royal-procession','The Queen Demands an Introduction','The court procession arrives and the Queen immediately tests Alice’s submission.','procession-lawn',{alice:'Names herself clearly, refuses to fear a pack of cards, and protects the gardeners by hiding them.','queen':'Questions Alice, condemns the gardeners, and orders everyone toward the croquet game.','king':'Follows the Queen and tries to soften confrontation without openly opposing her.','white-rabbit':'Appears as an anxious court attendant within the procession.','card-gardeners':'Lie hidden in a flowerpot after the Queen orders their execution.','knave':'Carries the King’s crown as part of the royal order.'},4,[]],
 [8,'croquet-chaos','Croquet with Flamingos','The royal game dissolves as animals move, arches wander, and players quarrel.','croquet',{alice:'Struggles to align flamingo and hedgehog while watching the Queen sentence everyone around her.',queen:'Treats missed turns and disputed paths as capital offences.',king:'Moves through the game under the Queen’s louder authority.','white-rabbit':'Keeps close enough to provide Alice cautious gossip about the Duchess.'},4,['flamingo']],
 [8,'cat-head','A Head without a Body','The Cheshire Cat’s head provokes a dispute over whether it can be beheaded.','cat-tree-royal',{alice:'Invites the Cat into conversation and points officials toward the Duchess as its owner.','cheshire-cat':'Leaves only its head visible, making ordinary execution logically impossible.',queen:'Orders the Cat beheaded rather than tolerating its amusement.',king:'Insists that anything with a head can be beheaded and calls for the executioner.'},3,[]],
 [9,'duchess-morals','Everything Has a Moral','The released Duchess walks closely beside Alice and attaches morals to every remark.','duchess-walk',{alice:'Endures the Duchess’s sharp chin while testing whether events need to carry forced lessons.',duchess:'Recasts her earlier hostility as intimacy and claims a moral for each observation.',queen:'Interrupts the reunion with a threat that sends the Duchess away.'},2,[]],
 [9,'gryphon-guide','The Queen’s Sentence Deferred','The Queen orders the Gryphon to take Alice to the Mock Turtle and claims previous sentences are complete.','shore-path',{alice:'Leaves the croquet ground curious about the Mock Turtle and doubtful that anyone has actually been executed.',queen:'Returns to the game after assuming her commands have been carried out.',gryphon:'Laughs at the Queen’s performance and guides Alice away without sharing her fear.'},2,[]],
 [9,'mock-school','The Mock Turtle’s School','The Mock Turtle recalls lessons that diminish each day and teachers with punning names.','seashore',{alice:'Listens seriously but keeps testing each schoolroom pun against ordinary education.',gryphon:'Prompts the story impatiently and corrects Alice when she takes words literally.','mock-turtle':'Turns memories of an undersea school into a melancholy catalogue of lessons and fees.'},2,[]],
 [10,'quadrille','The Lobster Quadrille','Gryphon and Mock Turtle demonstrate the dance around Alice.','seashore',{alice:'Moves through the positions while imagining an impossible dance with lobsters and whiting.',gryphon:'Directs the figures with energetic authority.','mock-turtle':'Sings the dance explanation and briefly escapes melancholy through performance.'},2,[]],
 [10,'alice-adventures','Alice Tells Her Adventures','Alice recounts the day until another altered recitation interrupts her account.','seashore',{alice:'Recognises that each explanation of the morning confirms how different she feels from yesterday.',gryphon:'Demands adventures before explanations and listens closely for further absurdity.','mock-turtle':'Treats Alice’s transformed verses as evidence that her experience is genuinely curious.'},2,[]],
 [10,'soup-song','Beautiful Soup','The Mock Turtle sings until the trial announcement cuts through the shore.','seashore',{alice:'Waits through the song, then runs when the distant court summons becomes clear.',gryphon:'Grabs Alice’s hand and hurries toward the trial without explaining the charge.','mock-turtle':'Continues the song as the others leave, his voice fading behind them.'},3,[]],
 [11,'trial-charge','The Knave Is Arraigned','The White Rabbit reads the accusation while the court surrounds the untouched tarts.','royal-dais',{alice:'Takes in judge, jury, defendant, and evidence while privately criticising the jurors’ premature notes.','white-rabbit':'Acts as herald, announces the charge, and manages the witness list.',queen:'Sits ready to sentence before evidence is heard.',king:'Presides as judge with crown over wig and asks for the first witness.',knave:'Stands in chains before the court without yet speaking.',jurors:'Write down their own names in case they forget them.'},4,['tarts']],
 [11,'hatter-evidence','The Hatter Gives Evidence','The Hatter’s unfinished tea and unreliable dates fail to satisfy the King.','witness-box',{alice:'Watches the witness shrink under royal questioning while noticing that she herself is growing.',hatter:'Arrives with bread-and-butter, cannot establish the date, and fears the Queen’s memory of his singing.','march-hare':'Denies the Hatter’s attempt to share responsibility.',dormouse:'Sleeps through being cited in the evidence.',queen:'Uses recognition from the concert as an implied death threat.',king:'Demands useful testimony but keeps converting wordplay into procedure.','white-rabbit':'Calls and dismisses witnesses according to the King’s commands.'},4,['tea-set','watch']],
 [11,'cook-evidence','Pepper, Not Tarts','The Cook names pepper as the material of tarts and refuses further explanation.','witness-box',{alice:'Observes the court lose control of another witness while her own size continues increasing.',cook:'Answers in single words, rejects the King’s question, and disappears from examination.',king:'Turns to the jury for help after the witness refuses him.',queen:'Calls for punishment when testimony does not obey the expected form.','white-rabbit':'Moves the hearing to the next witness.'},3,['pepper']],
 [12,'alice-called','Alice!','Alice is summoned so suddenly that she overturns the jury box.','jury-box',{alice:'Rises at near-normal size, restores the jurors to their box, and says she knows nothing about the tarts.',king:'Tries to exclude Alice using an improvised rule about height.',queen:'Supports any rule that removes resistance from the court.','white-rabbit':'Keeps the proceedings moving despite the overturned jury.',knave:'Remains accused while attention shifts toward Alice’s challenge.',jurors:'Are gathered from the floor and resume writing with slates in the wrong hands.'},4,['tarts']],
 [12,'letter-evidence','The Unsigned Letter','The Rabbit presents a letter whose lack of signature and unclear verse undermine the case.','tarts-table',{alice:'Tests each claim against the document and openly rejects meanings invented after the fact.','white-rabbit':'Reads the verse carefully and admits that it is not in the prisoner’s handwriting.',king:'Treats ambiguity as proof and constructs explanations line by line.',queen:'Demands sentence before verdict when the evidence fails to settle anything.',knave:'Points out that an unsigned letter cannot properly implicate him.',jurors:'Attempt to copy the King’s interpretations as though they were evidence.'},5,['letter','tarts']],
 [12,'cards-rise','You’re Nothing but a Pack of Cards','Alice rejects the Queen’s sentence and the whole court flies at her.','court-floor',{alice:'Reaches full confidence and names the court as cards rather than authorities.',queen:'Orders Alice’s head removed when legal performance no longer controls her.',king:'Loses the protection of procedure as the court dissolves into the attacking pack.','white-rabbit':'Is swept into the general collapse of court roles.',knave:'Disappears from importance once the accusation is exposed as nonsense.',jurors:'Become part of the flying pack rather than a deliberating body.'},5,['letter','tarts']],
 [12,'waking','The Riverbank Again','Alice wakes with leaves falling on her face and tells her sister the dream.','riverbank',{alice:'Returns to the summer bank carrying a coherent memory of Wonderland and runs home for tea.'},1,[]],
]
